const fs = require('node:fs');
const path = require('node:path');
const MarkdownIt = require('markdown-it');

process.chdir(path.resolve(__dirname, '../..'));
const navigation = JSON.parse(fs.readFileSync('docs/navigation.json', 'utf8'));
const articles = {};
const headings = new Map();
const links = [];
const highlighter = require('highlight.js/lib/core');
highlighter.registerLanguage('php', require('highlight.js/lib/languages/php'));
const markdown = new MarkdownIt({
    highlight(code, language) {
        if (!highlighter.getLanguage(language)) return '';
        return highlighter.highlight(code, { language }).value;
    }
});
const imageRoot = path.resolve('public/guide/images');

function visit(tokens, slug) {
    for (const [index, token] of tokens.entries()) {
        if (token.type === 'heading_open') {
            const title = tokens[index + 1].content.toLowerCase();
            let id = title.replace(/[^\p{L}\p{N} -]/gu, '').trim().replace(/\s+/g, '-');
            if (/^\d/.test(id)) id = '_' + id;
            const ids = headings.get(slug);
            const base = id;
            for (let n = 2; ids.has(id); n++) id = base + '-' + n;
            ids.add(id);
            token.attrSet('id', id);
        }
        if (token.type === 'link_open') {
            const href = token.attrGet('href');
            if (!/^https?:\/\//i.test(href) && !href.startsWith('mailto:')) {
                const [file, anchor] = href.split('#');
                const target = file ? path.posix.resolve('/', path.posix.dirname(slug), file).slice(1).replace(/\.md$/, '') : slug;
                links.push({ slug, target, anchor });
                token.attrSet('href', '?page=woopoly-guide&topic=' + encodeURIComponent(target) + (anchor ? '#' + anchor : ''));
            }
        }
        if (token.type === 'image') {
            const image = path.resolve('docs', path.dirname(slug), token.attrGet('src'));
            if (path.dirname(image) !== imageRoot || !fs.statSync(image).isFile()) throw new Error('Invalid image in ' + slug);
            token.attrSet('src', 'WOOPOLY_GUIDE_IMAGES/' + encodeURIComponent(path.basename(image)));
        }
        if (token.children) visit(token.children, slug);
    }
}

for (const topics of Object.values(navigation)) {
    for (const slug of Object.keys(topics)) {
        if (Object.hasOwn(articles, slug)) throw new Error('Duplicate topic: ' + slug);
        const tokens = markdown.parse(fs.readFileSync('docs/' + slug + '.md', 'utf8'), {});
        headings.set(slug, new Set());
        visit(tokens, slug);
        articles[slug] = markdown.renderer.render(tokens, markdown.options, {});
    }
}
for (const file of fs.readdirSync('docs', { recursive: true })) {
    if (file.endsWith('.md') && !Object.hasOwn(articles, file.slice(0, -3))) throw new Error('Unlisted article: ' + file);
}
for (const { slug, target, anchor } of links) {
    if (!headings.has(target) || (anchor && !headings.get(target).has(anchor))) {
        throw new Error('Broken link from ' + slug + ' to ' + target + '#' + (anchor || ''));
    }
}
const file = 'public/guide/articles.php';
const data = JSON.stringify({ navigation, articles }, null, 2);
const output = "<?php\n// Generated by npm run docs:build.\ndefined( 'ABSPATH' ) || exit;\nreturn json_decode( <<<'WOOPOLY_GUIDE'\n" + data + "\nWOOPOLY_GUIDE\n, true );\n";
if (process.argv.includes('--check')) {
    if (fs.readFileSync(file, 'utf8') !== output) throw new Error('Run npm run docs:build to update the bundled guide.');
} else {
    fs.writeFileSync(file, output);
}
console.log('Verified ' + headings.size + ' bundled guide articles and ' + links.length + ' internal links.');
